&lt;span id=&quot;p12R_mc7&quot; class=&quot;markedContent&quot;&gt;&lt;br&gt;&lt;span&gt;●&lt;/span&gt; &lt;span&gt;Strong knowledge of&lt;/span&gt; &lt;span&gt;MLOps frameworks&lt;/span&gt; &lt;span&gt;(ML&lt;/span&gt;&lt;span class=&quot;markedContent&quot;&gt;&lt;span&gt;ﬂ&lt;/span&gt;&lt;/span&gt;&lt;span&gt;ow, TFX) and&lt;/span&gt; &lt;span&gt;data governance tools &lt;/span&gt;&lt;span&gt;(DataHub, Amundsen).&lt;/span&gt;&lt;/span&gt;&lt;span id=&quot;p12R_mc8&quot; class=&quot;markedContent&quot;&gt;&lt;br&gt;&lt;/span&gt;&lt;span id=&quot;p12R_mc9&quot; class=&quot;markedContent&quot;&gt;&lt;br&gt;&lt;span&gt;Leadership Skills:&lt;/span&gt;&lt;/span&gt;&lt;span id=&quot;p12R_mc10&quot; class=&quot;markedContent&quot;&gt;&lt;br&gt;&lt;span&gt;●&lt;/span&gt; &lt;span&gt;Proven ability to inspire and lead teams while fostering a&lt;/span&gt; &lt;span&gt;culture of accountability and &lt;/span&gt;&lt;span&gt;excellence&lt;/span&gt;&lt;span&gt;.&lt;/span&gt;&lt;/span&gt;&lt;span id=&quot;p12R_mc11&quot; class=&quot;markedContent&quot;&gt;&lt;br&gt;&lt;span&gt;●&lt;/span&gt; &lt;span&gt;Exceptional leadership skills with a proven ability to&lt;/span&gt; &lt;span&gt;mentor engineers, lead projects&lt;/span&gt;&lt;span&gt;, and &lt;/span&gt;&lt;span&gt;work cross-functionally.&lt;/span&gt;&lt;/span&gt;&lt;span id=&quot;p12R_mc12&quot; class=&quot;markedContent&quot;&gt;&lt;br&gt;&lt;span&gt;●&lt;/span&gt; &lt;span&gt;Experience in&lt;/span&gt; &lt;span&gt;performance management, hiring, mentoring, and coaching engineers&lt;/span&gt;&lt;span&gt;.&lt;/span&gt;&lt;/span&gt;&lt;span id=&quot;p12R_mc13&quot; class=&quot;markedContent&quot;&gt;&lt;br&gt;&lt;span&gt;●&lt;/span&gt; &lt;span&gt;Strong collaboration skills with cross-functional teams and stakeholders.&lt;/span&gt;&lt;/span&gt;&lt;span id=&quot;p12R_mc14&quot; class=&quot;markedContent&quot;&gt;&lt;br&gt;&lt;/span&gt;&lt;/div&gt;
